tasks.check:
set -e
[ -e .venv ] || ln -s /home/bcorfman/dev/freytag-forge/.venv .venv
export PYTHONPATH=$PWD TMPDIR=/tmp
PY=.venv/bin/python
for f in $(git status --porcelain | grep -v '\.venv' | sed 's/^...//'); do
  case "$f" in
    data/stories/continuity-initiative/pacing.yaml|tests/test_2c_ledger_guard.py) ;;
    *) echo "WHY: edited file outside ownership: $f"; exit 1;;
  esac
done
git diff --quiet HEAD -- storygame packages tests/test_canon_journey.py tests/test_delivery_variants.py tests/test_reveal_prerequisites.py tests/test_stall_exit_audit.py || { echo "WHY: engine or protected tests edited"; exit 1; }
$PY - <<'EOF'
import subprocess, yaml
old = yaml.safe_load(subprocess.run(["git","show","HEAD:data/stories/continuity-initiative/pacing.yaml"],capture_output=True,text=True,check=True).stdout)
new = yaml.safe_load(open("data/stories/continuity-initiative/pacing.yaml"))
def evs(d):
    out = {}
    def walk(x):
        if isinstance(x, dict):
            if "id" in x and "scene_id" in x and ("at_turn" in x or "when" in x): out[x["id"]] = x
            for v in x.values(): walk(v)
        elif isinstance(x, list):
            for v in x: walk(v)
    walk(d); return out
a, b = evs(old), evs(new)
assert set(a) == set(b), "WHY: event ids changed"
changed = [i for i in a if a[i] != b[i]]
assert changed == ["audit_recovery_2b"], f"WHY: only audit_recovery_2b may change, got {changed}"
added = [w for w in b["audit_recovery_2b"]["when"] if w not in a["audit_recovery_2b"]["when"]]
want = [{"fact_id": "brandon_name_kept", "equals": False}, {"fact_id": "brandon_name_erased", "equals": False}]
assert sorted(map(str, added)) == sorted(map(str, want)), f"WHY: expected exactly the two ledger guards, got {added}"
assert all(w in b["audit_recovery_2b"]["when"] for w in a["audit_recovery_2b"]["when"]), "WHY: existing conditions removed"
assert {k: v for k, v in b["audit_recovery_2b"].items() if k != "when"} == {k: v for k, v in a["audit_recovery_2b"].items() if k != "when"}, "WHY: other fields of the event changed"
print("data ok")
EOF
$PY -m pytest -q -n0 -p no:cacheprovider tests/test_canon_journey.py tests/test_2c_ledger_guard.py tests/test_2c_turn_one_copy.py tests/test_reveal_prerequisites.py tests/test_stall_exit_audit.py tests/test_evidence_gap_journeys.py tests/test_evidence_penalty.py tests/test_markdown_story_package.py tests/test_spine_expected_reveals.py tests/test_incident_engine.py tests/test_incident_loader.py tests/test_incident_recovery.py tests/test_pacing_handoff.py tests/test_scene_relative_pacing.py $(ls tests/test_2b_*.py tests/test_3a_*.py tests/test_3b_*.py 2>/dev/null) > /tmp/r5.log 2>&1 || { tail -40 /tmp/r5.log; echo "WHY: focused suites failed"; exit 1; }
tail -3 /tmp/r5.log
$PY -m ruff format --check . && $PY -m ruff check . || { echo "WHY: ruff"; exit 1; }
OUT=/home/bcorfman/dev/ringer-work/act2-2c-yes
mkdir -p $OUT && git add -A >/dev/null 2>&1 && git diff --cached > $OUT/s2.patch && wc -l $OUT/s2.patch && git diff --cached --stat | tail -5
